local function make_readonly(tbl, name)
    local name = name or 'table'
    local proxy = {}
    local mt = {
        __index = tbl,
        __newindex = function(_, k, _)
            error(string.format("attempt to modify read-only %s at key '%s'", name, tostring(k)), 2)
        },
        __pairs = function()
            return next, tbl, nil
        },
        __len = function()
            return #tbl
        },
        __metatable = 'protected'
    }
    return setmetatable(proxy, mt)
end

return make_readonly

